/* EducaFAM — aplicação SPA-like em múltiplas páginas HTML, sem bibliotecas externas. */
const PAGE=document.body.dataset.page||'';
let session=getSession();
let account=session?getAccount(session.accountId):null;
let state={query:'',month:todayISO().slice(0,7)};

const NAV=[
  ['index.html','dashboard','⌂','Dashboard'],['financas.html','financas','▣','Finanças'],['metas.html','metas','◎','Metas'],['missoes.html','missoes','✓','Missões'],['criancas.html','criancas','◉','Crianças'],['relatorios.html','relatorios','▥','Relatórios'],['configuracoes.html','configuracoes','⚙','Configurações']
];

function $(id){return document.getElementById(id);}
function escapeHTML(value){return String(value??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));}
function htmlAttr(v){return escapeHTML(v).replace(/`/g,'&#96;');}
function getChild(id){return account?.children.find(c=>c.id===id);}
function getGoal(id){return account?.goals.find(g=>g.id===id);}
function getMission(id){return account?.missions.find(m=>m.id===id);}
function saveAccount(){try{upsertAccount(account);return true;}catch(e){toast('Não foi possível salvar. Verifique o espaço disponível no navegador.','error');return false;}}
function totals(month=null){
  const tx=account?.transactions||[];
  const list=month?tx.filter(t=>monthKey(t.date)===month):tx;
  const income=list.filter(t=>t.type==='income').reduce((s,t)=>s+Number(t.amount||0),0);
  const expense=list.filter(t=>t.type==='expense').reduce((s,t)=>s+Number(t.amount||0),0);
  return {income,expense,balance:income-expense};
}
function percent(saved,target){return target>0?Math.min(100,Math.max(0,Math.round(saved/target*100))):0;}
function goalStatus(g){
  if(Number(g.saved)>=Number(g.target))return 'concluida';
  if(g.deadline && g.deadline<todayISO())return 'atrasada';
  return 'andamento';
}
function statusLabel(s){return ({pending:'Pendente',in_progress:'Em andamento',awaiting:'Aguardando aprovação',approved:'Concluída',rejected:'Recusada'})[s]||s;}
function statusClass(s){return ({pending:'blue',in_progress:'gold',awaiting:'coral',approved:'green',rejected:'coral'})[s]||'blue';}
function childLevel(c){return levelForXP(c?.xp||0);}
function initials(name){return String(name||'?').split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase();}

function routeAllowed(){
  if(!session)return PAGE==='login';
  if(session.role==='child')return PAGE==='dashboard';
  return true;
}
function guard(){
  if(PAGE==='login')return;
  if(!session){window.location.href='login.html';return;}
  if(Date.now()>session.expiresAt){clearSession();window.location.href='login.html?expired=1';return;}
  if(session.role==='child' && PAGE!=='dashboard'){window.location.href='index.html';return;}
  touchSession();
  document.addEventListener('click',()=>touchSession(),{passive:true});
  document.addEventListener('keydown',()=>touchSession(),{passive:true});
}

function layout(content){
  const pending=account.missions.filter(m=>m.status==='awaiting').length;
  document.getElementById('app').innerHTML=`
  <div class="app-shell">
    <aside class="sidebar">
      <a class="brand" href="index.html" aria-label="EducaFAM - Dashboard"><div class="brand-mark">EF</div><div><div class="brand-name">Educa<span>FAM</span></div><div class="brand-sub">Finanças em família</div></div></a>
      <nav class="nav" aria-label="Navegação principal">
        ${NAV.map(n=>`<a href="${n[0]}" class="${PAGE===n[1]?'active':''}" ${PAGE===n[1]?'aria-current="page"':''}><span class="nav-icon" aria-hidden="true">${n[2]}</span><span>${n[3]}</span>${n[1]==='missoes'&&pending?`<b class="nav-count" aria-label="${pending} aguardando aprovação">${pending}</b>`:''}</a>`).join('')}
      </nav>
      <div class="sidebar-footer"><div class="family-mini"><strong>${escapeHTML(account.familyName||account.name)}</strong><span>${escapeHTML(account.responsible||'Responsável')}</span></div></div>
    </aside>
    <main class="main">
      <a class="skip-link" href="#main-content">Pular para o conteúdo</a>
      <header class="topbar">
        <div class="search"><span class="search-icon" aria-hidden="true">⌕</span><input id="globalSearch" type="search" placeholder="Buscar no sistema..." aria-label="Buscar no sistema"></div>
        <div class="top-actions">
          <button class="notification" id="notificationsBtn" type="button" aria-label="Notificações, ${pending} aguardando aprovação">♢${pending?`<span class="notification-dot" aria-hidden="true"></span>`:''}</button>
          <div class="user"><div class="avatar" aria-hidden="true">${initials(account.responsible)}</div><div><strong>${escapeHTML(account.responsible)}</strong><small>Responsável</small></div></div>
          <button class="btn btn-outline btn-small" type="button" id="logoutBtn">Sair</button>
        </div>
      </header>
      <section id="main-content" class="content" tabindex="-1">${content}</section>
    </main>
  </div>
  <div id="modal" class="modal" role="dialog" aria-modal="true" aria-hidden="true"></div>
  <div id="toast" class="toast" role="status" aria-live="polite"></div>`;
  bindGlobal();
}

function bindGlobal(){
  $('logoutBtn')?.addEventListener('click',logout);
  $('notificationsBtn')?.addEventListener('click',()=>showNotifications());
  $('globalSearch')?.addEventListener('input',e=>{state.query=e.target.value; if(PAGE==='financas')renderFinanceTable();});
}
function logout(){clearSession();window.location.href='login.html?logout=1';}
function toast(msg,type='ok'){
  const el=$('toast');if(!el)return;el.textContent=msg;el.className=`toast show ${type}`;clearTimeout(window.__toast);window.__toast=setTimeout(()=>el.classList.remove('show'),2800);
}
function openModal(title,body,onReady){
  const m=$('modal'); if(!m)return;
  m.innerHTML=`<div class="modal-box" tabindex="-1"><div class="modal-head"><h2 id="modal-title">${escapeHTML(title)}</h2><button class="close" type="button" aria-label="Fechar">×</button></div>${body}</div>`;
  m.classList.add('open');m.setAttribute('aria-hidden','false');m.querySelector('.close').addEventListener('click',closeModal);m.addEventListener('click',e=>{if(e.target===m)closeModal();});
  const box=m.querySelector('.modal-box');box.focus();m.__previousFocus=document.activeElement;onReady?.();
  m.addEventListener('keydown',modalKeydown);
}
function modalKeydown(e){if(e.key==='Escape'){closeModal();return;}if(e.key!=='Tab')return;const m=$('modal');const f=[...m.querySelectorAll('button,input,select,textarea,[tabindex]:not([tabindex="-1"])')].filter(x=>!x.disabled);if(!f.length)return;const first=f[0],last=f[f.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}
function closeModal(){const m=$('modal');if(!m)return;const prev=m.__previousFocus;m.classList.remove('open');m.setAttribute('aria-hidden','true');m.innerHTML='';m.removeEventListener('keydown',modalKeydown);prev?.focus?.();}
function confirmAction(title,message,action){openModal(title,`<p class="modal-copy">${escapeHTML(message)}</p><div class="form-actions"><button class="btn" type="button" id="cancelConfirm">Cancelar</button><button class="btn btn-danger" type="button" id="confirmAction">Confirmar</button></div>`,()=>{$('cancelConfirm').onclick=closeModal;$('confirmAction').onclick=()=>{closeModal();action();};});}
function showNotifications(){
  const unread=account.notifications.filter(n=>!n.read);
  openModal('Notificações',unread.length?`<div class="notification-list">${unread.map(n=>`<div class="notification-item"><b>${escapeHTML(n.text)}</b><small>${dateBR(n.date)}</small></div>`).join('')}</div><div class="form-actions"><button class="btn btn-primary" id="readNotifications">Marcar como lidas</button></div>`:`<div class="empty">Você está em dia. Nenhuma notificação nova.</div>`,()=>{$('readNotifications')?.addEventListener('click',()=>{account.notifications.forEach(n=>n.read=true);saveAccount();closeModal();toast('Notificações marcadas como lidas.');});});
}

function dashboard(){
  if(session.role==='child')return childDashboard();
  const t=totals(state.month), all=totals();
  const activeGoals=account.goals.filter(g=>goalStatus(g)!=='concluida').length;
  const awaiting=account.missions.filter(m=>m.status==='awaiting');
  return `<div class="page-head"><div><span class="eyebrow">Visão geral</span><h1>Olá, ${escapeHTML(account.responsible)}.</h1><p>Acompanhe as finanças, metas e o desenvolvimento das crianças.</p></div><div class="page-actions"><a class="btn btn-primary" href="financas.html">+ Nova movimentação</a><a class="btn" href="missoes.html">Nova missão</a></div></div>
  ${awaiting.length?`<div class="alert coral"><span aria-hidden="true">!</span><div><strong>${awaiting.length} missão${awaiting.length>1?'ões':''} aguardando aprovação</strong><small>Revise as atividades enviadas pelas crianças.</small></div><a href="missoes.html">Revisar</a></div>`:''}
  <div class="grid kpis"><div class="card kpi blue"><div class="label">Saldo familiar</div><div class="value">${money(all.balance)}</div><div class="delta">Acumulado de todas as movimentações</div></div><div class="card kpi green"><div class="label">Receitas no mês</div><div class="value">${money(t.income)}</div><div class="delta">${monthLabel(state.month)}</div></div><div class="card kpi coral"><div class="label">Despesas no mês</div><div class="value">${money(t.expense)}</div><div class="delta">${monthLabel(state.month)}</div></div><div class="card kpi gold"><div class="label">Metas ativas</div><div class="value">${activeGoals}</div><div class="delta">${account.goals.filter(g=>goalStatus(g)==='concluida').length} concluída(s)</div></div></div>
  <div class="grid two"><section class="card panel"><div class="panel-head"><div><div class="panel-title">Metas em andamento</div><div class="panel-sub">Progresso e prazo dos objetivos</div></div><a class="btn btn-soft" href="metas.html">Ver metas</a></div>${account.goals.slice(0,4).map(goalHTML).join('')||empty('Nenhuma meta cadastrada.')}</section>
  <section class="card panel"><div class="panel-head"><div><div class="panel-title">Progresso das crianças</div><div class="panel-sub">XP e nível atual</div></div><a class="btn btn-soft" href="criancas.html">Ver crianças</a></div>${account.children.map(childHTML).join('')||empty('Cadastre uma criança para começar.')}</section></div>
  <div class="grid two" style="margin-top:18px"><section class="card panel"><div class="panel-head"><div><div class="panel-title">Últimas movimentações</div><div class="panel-sub">Registros mais recentes</div></div><a class="btn btn-soft" href="financas.html">Ver extrato</a></div>${account.transactions.slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5).map(transactionRow).join('')||empty('Nenhuma movimentação.')}</section><section class="card panel"><div class="panel-head"><div><div class="panel-title">Missões da semana</div><div class="panel-sub">Atividades para desenvolver bons hábitos</div></div><a class="btn btn-soft" href="missoes.html">Ver missões</a></div>${account.missions.slice(0,4).map(missionRow).join('')||empty('Nenhuma missão.')}</section></div>`;
}
function empty(text){return `<div class="empty">${escapeHTML(text)}</div>`;}
function goalHTML(g){const p=percent(g.saved,g.target);const status=goalStatus(g);return `<div class="goal"><div class="goal-top"><div><strong>${escapeHTML(g.name)}</strong><small>${escapeHTML(g.category||'Sem categoria')} · ${g.type==='child'?'Individual':'Familiar'}</small></div><span class="badge ${status==='concluida'?'green':status==='atrasada'?'coral':'blue'}">${status==='concluida'?'Concluída':status==='atrasada'?'Atrasada':p+'%'}</span></div><div class="progress"><span style="width:${p}%"></span></div><div class="goal-meta"><span>${money(g.saved)} de ${money(g.target)} · faltam ${money(Math.max(0,g.target-g.saved))}</span><span>${g.deadline?dateBR(g.deadline):'Sem prazo'}</span></div></div>`;}
function childHTML(c){const xp=Number(c.xp)||0;const level=childLevel(c);const p=Math.round((xp%200)/2);return `<div class="child-row"><div class="child-avatar avatar-lg">${escapeHTML(c.avatar||initials(c.name))}</div><div class="child-main"><strong>${escapeHTML(c.name)}</strong><small>Nível ${level} · ${levelName(level)} · ${xp} XP</small><div class="progress" style="margin-top:7px"><span style="width:${p||100}%"></span></div></div><div class="child-xp">${remainingXP(xp)} XP<br><small>para o próximo nível</small></div></div>`;}
function transactionRow(t){return `<div class="setting-row"><div><strong>${escapeHTML(t.description)}</strong><small>${escapeHTML(t.category)} · ${dateBR(t.date)}</small></div><strong class="${t.type==='income'?'positive':'negative'}">${t.type==='income'?'+':'−'} ${money(t.amount)}</strong></div>`;}
function missionRow(m){return `<div class="mission"><span class="mission-icon" aria-hidden="true">${m.type==='Poupança'?'🐷':m.type==='Compras'?'🛒':m.type==='Registro de despesa'?'🧾':'✓'}</span><div class="mission-main"><strong>${escapeHTML(m.title)}</strong><small>${escapeHTML(getChild(m.childId)?.name||'Sem criança')} · ${statusLabel(m.status)}</small></div><span class="xp">+${Number(m.xp)||0} XP</span></div>`;}

function materializeRecurring(){
  if(!account?.transactions)return;
  const recurring=account.transactions.filter(t=>t.recurring&&!t.installment);
  let changed=false;
  for(const base of recurring){
    const d=new Date(`${base.date}T12:00:00`);
    for(let i=1;i<=2;i++){
      const next=new Date(d);next.setMonth(next.getMonth()+i);const nextDate=next.toISOString().slice(0,10);
      if(nextDate>todayISO()) break;
      const exists=account.transactions.some(t=>t.recurringSourceId===base.id&&t.date===nextDate);
      if(!exists){account.transactions.push({id:uid('tx'),type:base.type,amount:base.amount,description:base.description,category:base.category,date:nextDate,createdBy:base.createdBy,recurring:false,recurringSourceId:base.id});changed=true;}
    }
  }
  if(changed)saveAccount();
}

function finance(){
  const t=totals(state.month);return `<div class="page-head"><div><span class="eyebrow">Controle financeiro</span><h1>Finanças</h1><p>Registre receitas, despesas, compras parceladas e recorrências.</p></div><button class="btn btn-primary" id="newTransaction">+ Nova movimentação</button></div>
  <div class="toolbar"><div class="toolbar-left"><label class="compact-label">Mês<select class="select" id="monthFilter"></select></label><button class="btn" id="prevMonth">‹</button><button class="btn" id="nextMonth">›</button></div><div class="toolbar-right"><button class="btn" id="importCSV">Importar CSV</button><button class="btn" id="exportCSV">Exportar CSV</button><button class="btn" id="printReport">Imprimir / PDF</button></div></div>
  <div class="grid kpis"><div class="card kpi green"><div class="label">Receitas</div><div class="value">${money(t.income)}</div></div><div class="card kpi coral"><div class="label">Despesas</div><div class="value">${money(t.expense)}</div></div><div class="card kpi blue"><div class="label">Saldo do mês</div><div class="value">${money(t.balance)}</div></div><div class="card kpi gold"><div class="label">Movimentações</div><div class="value">${account.transactions.filter(x=>monthKey(x.date)===state.month).length}</div></div></div>
  <section class="card panel"><div class="toolbar"><div class="toolbar-left"><input class="input" id="financeFilter" placeholder="Filtrar descrição ou categoria..." aria-label="Filtrar lançamentos"><select class="select" id="typeFilter"><option value="">Todos os tipos</option><option value="income">Receitas</option><option value="expense">Despesas</option></select></div><a class="btn btn-soft" href="configuracoes.html#categorias">Categorias e orçamentos</a></div><div id="financeTable"></div></section>`;
}
function setupFinance(){
  fillMonthSelect($('monthFilter'));$('monthFilter').value=state.month;$('monthFilter').onchange=e=>{state.month=e.target.value;renderCurrent();};$('prevMonth').onclick=()=>changeMonth(-1);$('nextMonth').onclick=()=>changeMonth(1);$('newTransaction').onclick=()=>transactionModal();$('financeFilter').oninput=()=>renderFinanceTable();$('typeFilter').onchange=()=>renderFinanceTable();$('exportCSV').onclick=exportCSV;$('importCSV').onclick=importCSV;$('printReport').onclick=()=>window.print();renderFinanceTable();
}
function fillMonthSelect(select){if(!select)return;const keys=new Set();for(let i=0;i<12;i++){const d=new Date();d.setMonth(d.getMonth()-i);keys.add(d.toISOString().slice(0,7));}account.transactions.forEach(t=>keys.add(monthKey(t.date)));select.innerHTML=[...keys].sort().reverse().map(k=>`<option value="${k}">${monthLabel(k)}</option>`).join('');}
function changeMonth(delta){const d=new Date(`${state.month}-01T12:00:00`);d.setMonth(d.getMonth()+delta);state.month=d.toISOString().slice(0,7);renderCurrent();}
function renderFinanceTable(){const box=$('financeTable');if(!box)return;const q=($('financeFilter')?.value||state.query).toLowerCase();const type=$('typeFilter')?.value||'';const rows=account.transactions.filter(t=>monthKey(t.date)===state.month).filter(t=>(!type||t.type===type)&&(`${t.description} ${t.category}`.toLowerCase().includes(q)));box.innerHTML=`<div class="table-wrap"><table><thead><tr><th>Data</th><th>Descrição</th><th>Categoria</th><th>Tipo</th><th>Valor</th><th>Ações</th></tr></thead><tbody>${rows.map(t=>`<tr><td>${dateBR(t.date)}</td><td><strong>${escapeHTML(t.description)}</strong>${t.recurring?'<small class="table-note">Recorrente</small>':''}${t.installment?`<small class="table-note">Parcela ${t.installment.current}/${t.installment.total}</small>`:''}</td><td>${escapeHTML(t.category)}</td><td><span class="badge ${t.type==='income'?'green':'coral'}">${t.type==='income'?'Receita':'Despesa'}</span></td><td class="${t.type==='income'?'positive':'negative'}"><strong>${t.type==='income'?'+':'−'} ${money(t.amount)}</strong></td><td><div class="table-actions"><button class="btn btn-small" data-edit="${htmlAttr(t.id)}">Editar</button><button class="btn btn-small btn-danger-outline" data-delete="${htmlAttr(t.id)}">Excluir</button></div></td></tr>`).join('')||`<tr><td colspan="6">${empty('Nenhuma movimentação encontrada neste mês.')}</td></tr>`}</tbody></table></div>`;
  box.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>transactionModal(b.dataset.edit));box.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>deleteTransaction(b.dataset.delete));
}
function transactionModal(id=null){const t=id?account.transactions.find(x=>x.id===id):null;const cats=account.categories.filter(c=>c.name!=='Renda' || t?.type==='income');openModal(id?'Editar movimentação':'Nova movimentação',`<form id="txForm" class="form-grid"><label>Tipo<select id="txType"><option value="income" ${t?.type==='income'?'selected':''}>Receita</option><option value="expense" ${t?.type==='expense'||!t?'selected':''}>Despesa</option></select></label><label>Valor (R$)<input id="txAmount" type="number" step="0.01" min="0.01" value="${t?.amount||''}" required></label><label>Descrição<input id="txDescription" type="text" maxlength="100" value="${htmlAttr(t?.description||'')}" required></label><label>Categoria<select id="txCategory">${cats.map(c=>`<option ${t?.category===c.name?'selected':''}>${escapeHTML(c.name)}</option>`).join('')}</select></label><label>Data<input id="txDate" type="date" value="${t?.date||todayISO()}" required></label><label class="check-field"><input id="txRecurring" type="checkbox" ${t?.recurring?'checked':''}> Lançamento recorrente mensal</label><label>Parcelas<input id="txInstallments" type="number" min="1" max="60" value="${t?.installment?.total||1}"></label><div class="form-actions full"><button class="btn" type="button" id="cancelTx">Cancelar</button><button class="btn btn-primary" type="submit">Salvar</button></div></form>`,()=>{$('cancelTx').onclick=closeModal;$('txForm').onsubmit=e=>{e.preventDefault();const amount=Number($('txAmount').value);const desc=$('txDescription').value.trim();const date=$('txDate').value;if(!(amount>0)||!desc||!date){toast('Preencha os campos obrigatórios com valores válidos.','error');return;}const total=Math.max(1,Math.min(60,Number($('txInstallments').value)||1));if(id){Object.assign(t,{type:$('txType').value,amount,description:desc,category:$('txCategory').value,date,recurring:$('txRecurring').checked,installment:total>1?{current:t.installment?.current||1,total}:null});toast('Movimentação atualizada.');}else{if(total>1){for(let i=0;i<total;i++){const d=new Date(`${date}T12:00:00`);d.setMonth(d.getMonth()+i);account.transactions.push({id:uid('tx'),type:$('txType').value,amount:amount/total,description:`${desc} — parcela ${i+1}/${total}`,category:$('txCategory').value,date:d.toISOString().slice(0,10),createdBy:session.userId,installment:{current:i+1,total},recurring:false});}}else account.transactions.push({id:uid('tx'),type:$('txType').value,amount,description:desc,category:$('txCategory').value,date,createdBy:session.userId,recurring:$('txRecurring').checked,installment:null});toast('Movimentação adicionada.');}saveAccount();closeModal();renderCurrent();};});}
function deleteTransaction(id){const t=account.transactions.find(x=>x.id===id);if(!t)return;confirmAction('Excluir movimentação',`Excluir “${t.description}” de ${money(t.amount)}? Esta ação poderá ser desfeita por 5 segundos.`,()=>{const idx=account.transactions.findIndex(x=>x.id===id);const removed=account.transactions.splice(idx,1)[0];saveAccount();renderCurrent();const undo=document.createElement('button');undo.className='toast-undo';undo.textContent='Desfazer';undo.onclick=()=>{account.transactions.splice(idx,0,removed);saveAccount();renderCurrent();toast('Exclusão desfeita.');undo.remove();};document.body.appendChild(undo);setTimeout(()=>undo.remove(),5000);});}
function exportCSV(){const rows=account.transactions.filter(t=>monthKey(t.date)===state.month);const csv=[['Data','Descrição','Categoria','Tipo','Valor'],...rows.map(t=>[t.date,t.description,t.category,t.type,t.amount])].map(r=>r.map(v=>`"${String(v).replace(/"/g,'""')}"`).join(';')).join('\n');downloadBlob('\ufeff'+csv,'educafam-financas.csv','text/csv;charset=utf-8');}
function importCSV(){openModal('Importar CSV',`<p class="modal-copy">Use as colunas <strong>Data;Descrição;Categoria;Tipo;Valor</strong>. O tipo deve ser <strong>income</strong> ou <strong>expense</strong>.</p><input id="csvFile" type="file" accept=".csv,text/csv"><div class="form-actions"><button class="btn" id="cancelCsv">Cancelar</button><button class="btn btn-primary" id="processCsv">Importar</button></div>`,()=>{$('cancelCsv').onclick=closeModal;$('processCsv').onclick=()=>{const file=$('csvFile').files[0];if(!file){toast('Selecione um arquivo CSV.','error');return;}const r=new FileReader();r.onload=()=>{try{const lines=r.result.replace(/^\ufeff/,'').split(/\r?\n/).filter(Boolean);lines.shift();let count=0;for(const line of lines){const parts=line.split(';').map(v=>v.replace(/^"|"$/g,'').replace(/""/g,'"'));if(parts.length<5)continue;const [date,description,category,type,amount]=parts;if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!['income','expense'].includes(type)||!(Number(amount)>0))continue;account.transactions.push({id:uid('tx'),date,description,category,type,amount:Number(amount),createdBy:session.userId});count++;}saveAccount();closeModal();renderCurrent();toast(`${count} lançamento(s) importado(s).`);}catch{toast('CSV inválido.','error');}};r.readAsText(file,'utf-8');};});}

function metas(){return `<div class="page-head"><div><span class="eyebrow">Planejamento</span><h1>Metas</h1><p>Transforme objetivos em planos visuais de poupança para toda a família.</p></div><button class="btn btn-primary" id="newGoal">+ Nova meta</button></div><div class="grid three">${account.goals.map(g=>goalCard(g)).join('')||empty('Nenhuma meta cadastrada.')}</div><section class="card panel" style="margin-top:18px"><div class="panel-head"><div><div class="panel-title">Contribuições aguardando confirmação</div><div class="panel-sub">Confirme valores enviados pelos cofrinhos das crianças.</div></div></div>${pendingContributionsHTML()}</section><section class="card panel" style="margin-top:18px"><div class="panel-head"><div><div class="panel-title">Histórico de contribuições</div><div class="panel-sub">Quem contribuiu, quando e quanto</div></div></div><div id="contributionHistory">${contributionHistory()}</div></section>`;}
function goalCard(g){const p=percent(g.saved,g.target);const status=goalStatus(g);const remaining=Math.max(0,g.target-g.saved);const est=estimateGoal(g);return `<article class="card goal-card"><div class="goal-card-head"><span class="goal-symbol" aria-hidden="true">◎</span><div><h2>${escapeHTML(g.name)}</h2><small>${escapeHTML(g.category||'Sem categoria')} · ${g.type==='child'?'Individual':'Familiar'}</small></div><span class="badge ${status==='concluida'?'green':status==='atrasada'?'coral':'blue'}">${status==='concluida'?'Concluída':status==='atrasada'?'Atrasada':'Em andamento'}</span></div><div class="goal-big">${money(g.saved)} <small>de ${money(g.target)}</small></div><div class="progress"><span style="width:${p}%"></span></div><div class="goal-meta"><span>${p}% concluído</span><span>Faltam ${money(remaining)}</span></div><div class="goal-detail"><span>Prazo <b>${g.deadline?dateBR(g.deadline):'Sem prazo'}</b></span><span>Estimativa <b>${est}</b></span></div><div class="goal-actions"><button class="btn btn-primary" data-contribute="${g.id}">Contribuir</button><button class="btn" data-edit-goal="${g.id}">Editar</button><button class="btn btn-danger-outline" data-delete-goal="${g.id}">Excluir</button></div></article>`;}
function estimateGoal(g){if(g.saved>=g.target)return 'Concluída';const recent=(g.contributions||[]).filter(c=>c.amount>0).slice(-3);if(!recent.length)return 'Sem ritmo';const avg=recent.reduce((s,c)=>s+c.amount,0)/recent.length;const months=Math.ceil((g.target-g.saved)/avg);return `${months} mês${months>1?'es':''}`;}
function pendingContributionsHTML(){
  const rows=account.goals.flatMap(g=>(g.pendingContributions||[]).map(c=>({...c,goalId:g.id,goal:g.name})));
  if(!rows.length)return empty('Nenhuma contribuição aguardando confirmação.');
  return `<div class="table-wrap"><table><thead><tr><th>Meta</th><th>Criança</th><th>Data</th><th>Valor</th><th>Ações</th></tr></thead><tbody>${rows.map(c=>`<tr><td>${escapeHTML(c.goal)}</td><td>${escapeHTML(c.name)}</td><td>${dateBR(c.date)}</td><td>${money(c.amount)}</td><td><div class="table-actions"><button class="btn btn-small btn-primary" data-confirm-contribution="${c.goalId}|${c.id}">Confirmar</button><button class="btn btn-small btn-danger-outline" data-reject-contribution="${c.goalId}|${c.id}">Recusar</button></div></td></tr>`).join('')}</tbody></table></div>`;
}
function bindPendingContributions(){document.querySelectorAll('[data-confirm-contribution]').forEach(b=>b.onclick=()=>confirmContribution(b.dataset.confirmContribution));document.querySelectorAll('[data-reject-contribution]').forEach(b=>b.onclick=()=>rejectContribution(b.dataset.rejectContribution));}
function confirmContribution(key){const [goalId,pid]=key.split('|');const g=getGoal(goalId);const item=(g?.pendingContributions||[]).find(x=>x.id===pid);if(!g||!item)return;const amount=Math.min(item.amount,Math.max(0,g.target-g.saved));if(amount<=0){toast('A meta já foi concluída.','error');return;}confirmAction('Confirmar contribuição',`Adicionar ${money(amount)} à meta “${g.name}” e retirar o valor do cofrinho de ${item.name}?`,()=>{g.saved+=amount;g.contributions.push({id:uid('gc'),amount,by:item.by,name:item.name,date:todayISO()});const c=getChild(item.by);if(c)c.coffer=Math.max(0,c.coffer-amount);g.pendingContributions=g.pendingContributions.filter(x=>x.id!==pid);saveAccount();renderCurrent();toast('Contribuição confirmada.');});}
function rejectContribution(key){const [goalId,pid]=key.split('|');const g=getGoal(goalId);const item=(g?.pendingContributions||[]).find(x=>x.id===pid);if(!g||!item)return;confirmAction('Recusar contribuição',`Recusar a contribuição de ${item.name}? O valor continuará no cofrinho.`,()=>{g.pendingContributions=g.pendingContributions.filter(x=>x.id!==pid);saveAccount();renderCurrent();toast('Contribuição recusada.');});}

function contributionHistory(){const all=account.goals.flatMap(g=>(g.contributions||[]).map(c=>({...c,goal:g.name}))).sort((a,b)=>b.date.localeCompare(a.date));return all.length?`<div class="table-wrap"><table><thead><tr><th>Meta</th><th>Quem</th><th>Data</th><th>Valor</th></tr></thead><tbody>${all.map(c=>`<tr><td>${escapeHTML(c.goal)}</td><td>${escapeHTML(c.name||c.by||'—')}</td><td>${dateBR(c.date)}</td><td class="positive"><strong>+ ${money(c.amount)}</strong></td></tr>`).join('')}</tbody></table></div>`:empty('Ainda não há contribuições.');}
function setupMetas(){$('newGoal').onclick=()=>goalModal();bindPendingContributions();document.querySelectorAll('[data-contribute]').forEach(b=>b.onclick=()=>contributeModal(b.dataset.contribute));document.querySelectorAll('[data-edit-goal]').forEach(b=>b.onclick=()=>goalModal(b.dataset.editGoal));document.querySelectorAll('[data-delete-goal]').forEach(b=>b.onclick=()=>deleteGoal(b.dataset.deleteGoal));}
function goalModal(id=null){const g=id?getGoal(id):null;openModal(id?'Editar meta':'Nova meta',`<form id="goalForm" class="form-grid"><label>Nome<input id="goalName" maxlength="80" value="${htmlAttr(g?.name||'')}" required></label><label>Valor alvo (R$)<input id="goalTarget" type="number" min="0.01" step="0.01" value="${g?.target||''}" required></label><label>Prazo<input id="goalDeadline" type="date" min="${todayISO()}" value="${g?.deadline||''}" required></label><label>Categoria<input id="goalCategory" maxlength="40" value="${htmlAttr(g?.category||'')}" required></label><label>Tipo<select id="goalType"><option value="family" ${g?.type!=='child'?'selected':''}>Familiar</option><option value="child" ${g?.type==='child'?'selected':''}>Individual de uma criança</option></select></label><label id="goalChildWrap">Criança<select id="goalChild">${account.children.map(c=>`<option value="${c.id}" ${g?.childId===c.id?'selected':''}>${escapeHTML(c.name)}</option>`).join('')}</select></label><div class="form-actions full"><button class="btn" type="button" id="cancelGoal">Cancelar</button><button class="btn btn-primary">Salvar meta</button></div></form>`,()=>{const toggle=()=>{$('goalChildWrap').style.display=$('goalType').value==='child'?'flex':'none';};$('goalType').onchange=toggle;toggle();$('cancelGoal').onclick=closeModal;$('goalForm').onsubmit=e=>{e.preventDefault();const name=$('goalName').value.trim(),target=Number($('goalTarget').value),deadline=$('goalDeadline').value;if(!name||!(target>0)||!deadline||deadline<todayISO()){toast('Informe nome, valor maior que zero e prazo futuro.','error');return;}if(id){Object.assign(g,{name,target,deadline,category:$('goalCategory').value.trim(),type:$('goalType').value,childId:$('goalType').value==='child'?$('goalChild').value:null});}else account.goals.push({id:uid('goal'),name,target,saved:0,deadline,category:$('goalCategory').value.trim(),type:$('goalType').value,childId:$('goalType').value==='child'?$('goalChild').value:null,contributions:[]});saveAccount();closeModal();renderCurrent();toast(id?'Meta atualizada.':'Meta criada.');};});}
function contributeModal(goalId,childId=null){const g=getGoal(goalId);if(!g)return;const child=childId?getChild(childId):null;openModal('Contribuir para meta',`<form id="contribForm"><p class="modal-copy"><strong>${escapeHTML(g.name)}</strong><br>Restante: ${money(Math.max(0,g.target-g.saved))}</p><label>Valor (R$)<input id="contribAmount" type="number" min="0.01" max="${Math.max(0,g.target-g.saved)}" step="0.01" required></label><div class="form-actions"><button class="btn" type="button" id="cancelContrib">Cancelar</button><button class="btn btn-primary">Adicionar contribuição</button></div></form>`,()=>{$('cancelContrib').onclick=closeModal;$('contribForm').onsubmit=e=>{e.preventDefault();const amount=Number($('contribAmount').value);const remaining=g.target-g.saved;if(!(amount>0)||amount>remaining){toast('A contribuição não pode ultrapassar o valor restante.','error');return;}g.saved+=amount;g.contributions.push({id:uid('gc'),amount,by:child?child.id:session.userId,name:child?child.name:account.responsible,date:todayISO(),pending:false});if(child){child.coffer=Math.max(0,child.coffer-amount);}saveAccount();closeModal();renderCurrent();toast('Contribuição registrada.');};});}
function deleteGoal(id){const g=getGoal(id);if(!g)return;confirmAction('Excluir meta',`Excluir “${g.name}” e seu histórico de contribuições?`,()=>{account.goals=account.goals.filter(x=>x.id!==id);saveAccount();renderCurrent();toast('Meta excluída.');});}

function missoes(){const awaiting=account.missions.filter(m=>m.status==='awaiting').length;return `<div class="page-head"><div><span class="eyebrow">Educação financeira</span><h1>Missões</h1><p>Crie atividades práticas, acompanhe entregas e aprove as conquistas.</p></div><button class="btn btn-primary" id="newMission">+ Nova missão</button></div>${awaiting?`<div class="alert coral"><span>!</span><div><strong>${awaiting} missão${awaiting>1?'ões':''} aguardando aprovação</strong><small>O XP só é creditado após a aprovação.</small></div></div>`:''}<section class="card panel"><div class="toolbar"><div class="toolbar-left"><select class="select" id="missionStatus"><option value="">Todos os estados</option><option value="pending">Pendentes</option><option value="in_progress">Em andamento</option><option value="awaiting">Aguardando aprovação</option><option value="approved">Concluídas</option><option value="rejected">Recusadas</option></select><select class="select" id="missionChild"><option value="">Todas as crianças</option>${account.children.map(c=>`<option value="${c.id}">${escapeHTML(c.name)}</option>`).join('')}</select></div></div><div id="missionList">${missionCards()}</div></section>`;}
function missionCards(){const status=$('missionStatus')?.value||'',childId=$('missionChild')?.value||'';const list=account.missions.filter(m=>(!status||m.status===status)&&(!childId||m.childId===childId));return list.length?list.map(m=>`<article class="mission-card"><div class="mission-card-top"><div class="mission-icon big">${m.type==='Poupança'?'🐷':m.type==='Compras'?'🛒':m.type==='Registro de despesa'?'🧾':m.type==='Organização'?'🗂️':'📘'}</div><div class="mission-card-main"><h2>${escapeHTML(m.title)}</h2><p>${escapeHTML(m.description||'')}</p><div class="mission-meta"><span>${escapeHTML(getChild(m.childId)?.name||'Sem criança')}</span><span>${escapeHTML(m.type)}</span>${m.deadline?`<span>Prazo ${dateBR(m.deadline)}</span>`:''}</div></div><div><span class="badge ${statusClass(m.status)}">${statusLabel(m.status)}</span><strong class="xp">+${m.xp} XP</strong></div></div>${m.submission?`<div class="submission"><b>Entrega:</b> ${escapeHTML(m.submission.description||'')} ${m.submission.amount?`· ${money(m.submission.amount)}`:''}</div>`:''}${m.reviewComment?`<div class="review-comment"><b>Comentário:</b> ${escapeHTML(m.reviewComment)}</div>`:''}<div class="mission-actions">${m.status==='awaiting'?`<button class="btn btn-primary" data-approve="${m.id}">Aprovar</button><button class="btn btn-danger-outline" data-reject="${m.id}">Recusar</button>`:''}<button class="btn" data-edit-mission="${m.id}">Editar</button><button class="btn btn-danger-outline" data-delete-mission="${m.id}">Excluir</button></div></article>`).join(''):empty('Nenhuma missão encontrada.');}
function setupMissoes(){ $('newMission').onclick=()=>missionModal();$('missionStatus').onchange=()=>{$('missionList').innerHTML=missionCards();bindMissionActions();};$('missionChild').onchange=()=>{$('missionList').innerHTML=missionCards();bindMissionActions();};bindMissionActions();}
function bindMissionActions(){document.querySelectorAll('[data-approve]').forEach(b=>b.onclick=()=>reviewMission(b.dataset.approve,true));document.querySelectorAll('[data-reject]').forEach(b=>b.onclick=()=>reviewMission(b.dataset.reject,false));document.querySelectorAll('[data-edit-mission]').forEach(b=>b.onclick=()=>missionModal(b.dataset.editMission));document.querySelectorAll('[data-delete-mission]').forEach(b=>b.onclick=()=>deleteMission(b.dataset.deleteMission));}
function missionModal(id=null){const m=id?getMission(id):null;openModal(id?'Editar missão':'Nova missão',`<form id="missionForm" class="form-grid"><label>Título<input id="mTitle" maxlength="80" value="${htmlAttr(m?.title||'')}" required></label><label>XP<input id="mXP" type="number" min="1" max="1000" value="${m?.xp||50}" required></label><label class="full">Descrição<textarea id="mDescription" rows="3" maxlength="300" required>${escapeHTML(m?.description||'')}</textarea></label><label>Tipo<select id="mType">${['Poupança','Compras','Registro de despesa','Organização','Educação financeira'].map(x=>`<option ${m?.type===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Criança<select id="mChild">${account.children.map(c=>`<option value="${c.id}" ${m?.childId===c.id?'selected':''}>${escapeHTML(c.name)}</option>`).join('')}</select></label><label>Prazo opcional<input id="mDeadline" type="date" min="${todayISO()}" value="${m?.deadline||''}"></label><label>Meta vinculada<select id="mGoal"><option value="">Nenhuma</option>${account.goals.filter(g=>g.type==='family').map(g=>`<option value="${g.id}" ${m?.linkedGoalId===g.id?'selected':''}>${escapeHTML(g.name)}</option>`).join('')}</select></label><div class="form-actions full"><button class="btn" type="button" id="cancelMission">Cancelar</button><button class="btn btn-primary">Salvar missão</button></div></form>`,()=>{$('cancelMission').onclick=closeModal;$('missionForm').onsubmit=e=>{e.preventDefault();const title=$('mTitle').value.trim(),desc=$('mDescription').value.trim(),xp=Number($('mXP').value);if(!title||!desc||!(xp>0)||!$('mChild').value){toast('Preencha título, descrição, XP e criança.','error');return;}if($('mType').value==='Poupança'&&!$('mGoal').value){toast('Missões de poupança precisam de uma meta vinculada.','error');return;}if(id)Object.assign(m,{title,description:desc,xp,type:$('mType').value,childId:$('mChild').value,deadline:$('mDeadline').value||null,linkedGoalId:$('mGoal').value||null});else account.missions.push({id:uid('mission'),title,description:desc,xp,type:$('mType').value,childId:$('mChild').value,deadline:$('mDeadline').value||null,status:'pending',linkedGoalId:$('mGoal').value||null,createdAt:todayISO(),submission:null,reviewComment:''});saveAccount();closeModal();renderCurrent();toast(id?'Missão atualizada.':'Missão criada.');};});}
function reviewMission(id,approve){const m=getMission(id);if(!m)return;if(approve){confirmAction('Aprovar missão','O XP será creditado e a integração financeira/meta será executada quando aplicável.',()=>approveMission(m));}else{openModal('Recusar missão',`<label>Comentário para a criança<textarea id="rejectComment" rows="4" maxlength="300" placeholder="Explique o que precisa ser ajustado."></textarea></label><div class="form-actions"><button class="btn" id="cancelReject">Cancelar</button><button class="btn btn-danger" id="confirmReject">Recusar missão</button></div>`,()=>{$('cancelReject').onclick=closeModal;$('confirmReject').onclick=()=>{const comment=$('rejectComment').value.trim();if(!comment){toast('Informe um comentário.','error');return;}m.status='rejected';m.reviewComment=comment;saveAccount();closeModal();renderCurrent();toast('Missão recusada.');};});}}
function approveMission(m){const child=getChild(m.childId);if(!child)return;m.status='approved';m.reviewComment='Aprovada pelo responsável.';child.xp+=Number(m.xp)||0;account.xpHistory.push({id:uid('xp'),childId:child.id,amount:Number(m.xp)||0,reason:`Missão aprovada: ${m.title}`,date:todayISO()});if(m.type==='Registro de despesa'&&m.submission?.amount){account.transactions.push({id:uid('tx'),type:'expense',description:m.submission.description||m.title,category:'Educação financeira',amount:Number(m.submission.amount),date:todayISO(),createdBy:session.userId,sourceMissionId:m.id});}if(m.type==='Poupança'&&m.submission?.amount&&m.linkedGoalId){const g=getGoal(m.linkedGoalId);if(g){const amount=Math.min(Number(m.submission.amount),Math.max(0,g.target-g.saved),Math.max(0,child.coffer));g.saved+=amount;g.contributions.push({id:uid('gc'),amount,by:child.id,name:child.name,date:todayISO(),missionId:m.id});child.coffer=Math.max(0,child.coffer-amount);}}account.notifications.unshift({id:uid('n'),text:`${child.name} ganhou ${m.xp} XP em “${m.title}”.`,date:todayISO(),read:false,type:'xp'});saveAccount();closeModal();renderCurrent();toast('Missão aprovada e XP creditado!');}
function deleteMission(id){confirmAction('Excluir missão','Esta ação remove a missão e seu histórico de aprovação.',()=>{account.missions=account.missions.filter(m=>m.id!==id);saveAccount();renderCurrent();toast('Missão excluída.');});}

function criancas(){return `<div class="page-head"><div><span class="eyebrow">Participação infantil</span><h1>Crianças</h1><p>Gerencie perfis, PINs, progresso e participação nas metas.</p></div><button class="btn btn-primary" id="newChild">+ Nova criança</button></div><div class="grid two">${account.children.map(c=>childCard(c)).join('')||empty('Nenhuma criança cadastrada.')}</div>`;}
function childCard(c){const level=childLevel(c);const xp=(c.xp%200)/2;const missions=account.missions.filter(m=>m.childId===c.id);const completed=missions.filter(m=>m.status==='approved').length;return `<article class="card panel child-card"><div class="child-profile"><div class="child-avatar avatar-xl">${escapeHTML(c.avatar||'🙂')}</div><div><h2>${escapeHTML(c.name)}</h2><p>${c.age?c.age+' anos · ':''}Nível ${level} · ${levelName(level)}</p></div><span class="badge gold">${c.xp} XP</span></div><div class="progress"><span style="width:${xp||100}%"></span></div><div class="child-stats"><span><b>${completed}</b> missões concluídas</span><span><b>${money(c.coffer)}</b> no cofrinho</span></div><div class="child-actions"><button class="btn btn-primary" data-child-login="${c.id}">Entrar como criança</button><button class="btn" data-edit-child="${c.id}">Editar</button><button class="btn btn-danger-outline" data-delete-child="${c.id}">Excluir</button></div></article>`;}
function setupCriancas(){$('newChild').onclick=()=>childModal();document.querySelectorAll('[data-child-login]').forEach(b=>b.onclick=()=>enterChild(b.dataset.childLogin));document.querySelectorAll('[data-edit-child]').forEach(b=>b.onclick=()=>childModal(b.dataset.editChild));document.querySelectorAll('[data-delete-child]').forEach(b=>b.onclick=()=>deleteChild(b.dataset.deleteChild));}
function childModal(id=null){const c=id?getChild(id):null;openModal(id?'Editar criança':'Cadastrar criança',`<form id="childForm" class="form-grid"><label>Nome<input id="cName" maxlength="40" value="${htmlAttr(c?.name||'')}" required></label><label>Idade<input id="cAge" type="number" min="4" max="17" value="${c?.age||''}" required></label><label>Avatar<div class="avatar-picker" id="avatarPicker">${AVATARS.map(a=>`<button type="button" class="avatar-choice ${c?.avatar===a?'selected':''}" data-avatar="${a}" aria-label="Avatar ${a}">${a}</button>`).join('')}</div></label><label>PIN de 4 dígitos ${id?'<small>Deixe vazio para manter o atual.</small>':''}<input id="cPin" inputmode="numeric" pattern="[0-9]{4}" maxlength="4" type="password" placeholder="1234" ${id?'':'required'}></label><label class="check-field full"><input id="cConsent" type="checkbox" ${account.consentMinor?'checked':''} required> Confirmo que sou responsável e autorizo o cadastro deste menor.</label><div class="form-actions full"><button class="btn" type="button" id="cancelChild">Cancelar</button><button class="btn btn-primary">Salvar</button></div></form>`,()=>{let avatar=c?.avatar||AVATARS[0];document.querySelectorAll('[data-avatar]').forEach(b=>b.onclick=()=>{avatar=b.dataset.avatar;document.querySelectorAll('[data-avatar]').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');});$('cancelChild').onclick=closeModal;$('childForm').onsubmit=async e=>{e.preventDefault();if(!account.consentMinor){toast('O responsável precisa autorizar o cadastro de menores.','error');return;}const name=$('cName').value.trim(),age=Number($('cAge').value),pin=$('cPin').value.trim();if(!name||age<4||age>17||(!id&&!/^\d{4}$/.test(pin))||(id&&pin&&!/^\d{4}$/.test(pin))){toast('Preencha os dados e use um PIN de exatamente 4 dígitos.','error');return;}if(id){c.name=name;c.age=age;c.avatar=avatar;if(pin)c.pin=await hashSecret(pin);}else account.children.push({id:uid('child'),name,age,avatar,pin:await hashSecret(pin),xp:0,coffer:0,createdAt:todayISO()});saveAccount();closeModal();renderCurrent();toast(id?'Perfil atualizado.':'Criança cadastrada.');};});}
function enterChild(childId){const c=getChild(childId);if(!c)return;openModal(`Entrar como ${c.name}`,`<div class="child-login-preview"><div class="avatar-xl">${escapeHTML(c.avatar)}</div><h3>${escapeHTML(c.name)}</h3><p>Digite o PIN de 4 dígitos para acessar o espaço infantil.</p></div><label>PIN<input id="childPinLogin" type="password" inputmode="numeric" maxlength="4" pattern="[0-9]{4}" autocomplete="off"></label><div class="form-actions"><button class="btn" id="cancelChildLogin">Cancelar</button><button class="btn btn-primary" id="confirmChildLogin">Entrar</button></div>`,()=>{$('cancelChildLogin').onclick=closeModal;$('confirmChildLogin').onclick=async()=>{const pin=$('childPinLogin').value;if(!/^\d{4}$/.test(pin)){toast('Digite um PIN de 4 dígitos.','error');return;}if(await verifySecret(pin,c.pin)){setSession({accountId:account.id,role:'child',childId:c.id,userId:c.id,expiresAt:Date.now()+30*60*1000,lastActivity:Date.now()});window.location.href='index.html';}else toast('PIN incorreto.','error');};});}
function deleteChild(id){const c=getChild(id);if(!c)return;confirmAction('Excluir perfil infantil',`Excluir ${c.name}? As missões e contribuições já registradas serão mantidas no histórico, mas o perfil será removido.`,()=>{account.children=account.children.filter(x=>x.id!==id);account.missions.forEach(m=>{if(m.childId===id)m.childId=null;});saveAccount();renderCurrent();toast('Perfil infantil removido.');});}

function childDashboard(){const c=getChild(session.childId);if(!c){clearSession();location.href='login.html';return '';}const missions=account.missions.filter(m=>m.childId===c.id);const goals=account.goals.filter(g=>g.type==='family'||g.childId===c.id);const level=childLevel(c),progress=(c.xp%200)/2;return `<div class="child-mode"><div class="child-hero"><div><span class="eyebrow">Meu espaço</span><h1>Olá, ${escapeHTML(c.name)}! ${escapeHTML(c.avatar)}</h1><p>Aprenda, cumpra missões e ajude sua família a alcançar metas.</p></div><div class="child-level"><strong>Nível ${level}</strong><span>${escapeHTML(levelName(level))}</span><div class="progress"><span style="width:${progress||100}%"></span></div><small>${remainingXP(c.xp)} XP para o próximo nível</small></div></div><div class="child-nav" role="navigation" aria-label="Menu infantil"><button class="active" data-child-tab="missoes">✓ Minhas missões</button><button data-child-tab="metas">◎ Minhas metas</button><button data-child-tab="progresso">★ Meu progresso</button><button data-child-tab="cofrinho">🐷 Cofrinho</button></div><div id="childTabContent">${childTab('missoes')}</div></div>`;}
function childTab(tab){const c=getChild(session.childId);if(tab==='metas')return `<section class="child-section"><div class="section-title"><h2>Minhas metas</h2><p>Veja onde sua família quer chegar.</p></div><div class="grid two">${account.goals.filter(g=>g.type==='family'||g.childId===c.id).map(g=>`<article class="card child-goal"><h3>${escapeHTML(g.name)}</h3><p>${money(g.saved)} de ${money(g.target)}</p><div class="progress"><span style="width:${percent(g.saved,g.target)}%"></span></div><small>${percent(g.saved,g.target)}% · ${g.deadline?`até ${dateBR(g.deadline)}`:'sem prazo'}</small>${g.type==='family'?`<button class="btn btn-primary" data-child-contribute="${g.id}">Contribuir com meu cofrinho</button>`:''}</article>`).join('')||empty('Nenhuma meta disponível.')}</div></section>`;if(tab==='progresso'){const hist=account.xpHistory.filter(x=>x.childId===c.id).slice().reverse();return `<section class="child-section"><div class="section-title"><h2>Meu progresso</h2><p>Você já conquistou ${c.xp} XP e está no nível ${childLevel(c)}.</p></div><div class="grid three"><div class="card child-stat"><span>XP total</span><strong>${c.xp}</strong></div><div class="card child-stat"><span>Nível</span><strong>${childLevel(c)}</strong></div><div class="card child-stat"><span>Cofrinho</span><strong>${money(c.coffer)}</strong></div></div><div class="card panel" style="margin-top:18px"><h3>Histórico de XP</h3>${hist.length?hist.map(x=>`<div class="setting-row"><div><strong>${escapeHTML(x.reason)}</strong><small>${dateBR(x.date)}</small></div><b class="positive">+${x.amount} XP</b></div>`).join(''):empty('Seu histórico aparecerá aqui.')}</div></section>`;}if(tab==='cofrinho')return `<section class="child-section"><div class="coffer-card"><div class="coffer-emoji">🐷</div><div><span>Meu cofrinho</span><strong>${money(c.coffer)}</strong><p>Você pode guardar dinheiro e usar parte dele para contribuir com metas familiares.</p></div></div><div class="card panel"><h3>Adicionar dinheiro ao cofrinho</h3><form id="cofferForm" class="inline-form"><label>Valor (R$)<input id="cofferAmount" type="number" min="0.01" step="0.01" required></label><button class="btn btn-primary">Guardar</button></form></div></section>`;return `<section class="child-section"><div class="section-title"><h2>Minhas missões</h2><p>Faça uma atividade, envie para aprovação e conquiste XP.</p></div>${account.missions.filter(m=>m.childId===c.id).map(m=>`<article class="card child-mission"><div class="mission-card-top"><div class="mission-icon big">${m.type==='Poupança'?'🐷':m.type==='Compras'?'🛒':m.type==='Registro de despesa'?'🧾':'📘'}</div><div class="mission-card-main"><h3>${escapeHTML(m.title)}</h3><p>${escapeHTML(m.description||'')}</p><div class="mission-meta"><span>${escapeHTML(m.type)}</span>${m.deadline?`<span>Prazo ${dateBR(m.deadline)}</span>`:''}</div></div><span class="badge ${statusClass(m.status)}">${statusLabel(m.status)}</span></div>${m.status==='pending'||m.status==='rejected'?`<button class="btn btn-primary" data-do-mission="${m.id}">${m.status==='rejected'?'Enviar novamente':'Marcar como feita'}</button>`:''}${m.status==='awaiting'?`<div class="awaiting-box">Enviada para o responsável. Aguarde a aprovação.</div>`:''}${m.status==='approved'?`<div class="approved-box">✓ Concluída! Você ganhou ${m.xp} XP.</div>`:''}${m.status==='rejected'?`<div class="review-comment"><b>O responsável pediu:</b> ${escapeHTML(m.reviewComment)}</div>`:''}</article>`).join('')||empty('Você ainda não recebeu missões.')}</section>`;}
function setupChildDashboard(){document.querySelectorAll('[data-child-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-child-tab]').forEach(x=>x.classList.remove('active'));b.classList.add('active');$('childTabContent').innerHTML=childTab(b.dataset.childTab);bindChildTab();});bindChildTab();}
function bindChildTab(){document.querySelectorAll('[data-do-mission]').forEach(b=>b.onclick=()=>submitChildMission(b.dataset.doMission));document.querySelectorAll('[data-child-contribute]').forEach(b=>b.onclick=()=>childContribute(b.dataset.childContribute));$('cofferForm')?.addEventListener('submit',e=>{e.preventDefault();const c=getChild(session.childId),amount=Number($('cofferAmount').value);if(!(amount>0)){toast('Informe um valor válido.','error');return;}c.coffer+=amount;saveAccount();$('childTabContent').innerHTML=childTab('cofrinho');bindChildTab();toast('Dinheiro guardado no cofrinho!');});}
function submitChildMission(id){const m=getMission(id);if(!m)return;openModal('Enviar missão para aprovação',`<form id="submitMissionForm"><p class="modal-copy">${escapeHTML(m.title)}</p>${(m.type==='Registro de despesa'||m.type==='Poupança')?`<label>${m.type==='Registro de despesa'?'Valor da despesa':'Valor guardado'} (R$)<input id="submissionAmount" type="number" min="0.01" step="0.01" required></label>`:''}<label>O que você fez?<textarea id="submissionDescription" rows="4" maxlength="300" required placeholder="Conte ao responsável como realizou a missão."></textarea></label><div class="form-actions"><button class="btn" id="cancelSubmit">Cancelar</button><button class="btn btn-primary">Enviar</button></div></form>`,()=>{$('cancelSubmit').onclick=closeModal;$('submitMissionForm').onsubmit=e=>{e.preventDefault();const desc=$('submissionDescription').value.trim();const amount=$('submissionAmount')?Number($('submissionAmount').value):null;if(!desc||((m.type==='Registro de despesa'||m.type==='Poupança')&&!(amount>0))){toast('Preencha a entrega da missão.','error');return;}if(m.type==='Poupança'&&amount>getChild(session.childId).coffer){toast('O valor informado é maior que o saldo do seu cofrinho.','error');return;}m.submission={description:desc,amount};m.status='awaiting';account.notifications.unshift({id:uid('n'),text:`${getChild(session.childId).name} enviou a missão “${m.title}” para aprovação.`,date:todayISO(),read:false,type:'mission'});saveAccount();closeModal();renderCurrent();toast('Missão enviada para aprovação!');};});}
function childContribute(goalId){const c=getChild(session.childId),g=getGoal(goalId);if(!g)return;openModal('Contribuir com o cofrinho',`<p class="modal-copy">Cofrinho disponível: <strong>${money(c.coffer)}</strong><br>Restante da meta: <strong>${money(Math.max(0,g.target-g.saved))}</strong></p><form id="childContributionForm"><label>Valor (R$)<input id="childContributionAmount" type="number" min="0.01" max="${Math.min(c.coffer,Math.max(0,g.target-g.saved))}" step="0.01" required></label><div class="form-actions"><button class="btn" id="cancelChildContrib">Cancelar</button><button class="btn btn-primary">Enviar contribuição</button></div></form>`,()=>{$('cancelChildContrib').onclick=closeModal;$('childContributionForm').onsubmit=e=>{e.preventDefault();const amount=Number($('childContributionAmount').value);if(!(amount>0)||amount>c.coffer||amount>g.target-g.saved){toast('Verifique o valor disponível e o restante da meta.','error');return;}g.pendingContributions=g.pendingContributions||[];g.pendingContributions.push({id:uid('pc'),amount,by:c.id,name:c.name,date:todayISO()});account.notifications.unshift({id:uid('n'),text:`${c.name} enviou ${money(amount)} para a meta “${g.name}”. Confirme a contribuição.`,date:todayISO(),read:false,type:'goal'});saveAccount();closeModal();renderCurrent();toast('Contribuição enviada para confirmação.');};});}

function relatorios(){const t=totals(state.month),prevMonth=getPreviousMonth(state.month),prev=totals(prevMonth);const saving=t.income?t.balance/t.income*100:0;const cat=expenseByCategory(state.month);const awaiting=account.missions.filter(m=>m.status==='awaiting').length;return `<div class="page-head"><div><span class="eyebrow">Análise</span><h1>Relatórios</h1><p>Veja tendências financeiras, metas e evolução das crianças.</p></div><div class="page-actions"><select class="select" id="reportMonth"></select><button class="btn btn-primary" id="printReport">Imprimir / PDF</button></div></div><div class="grid kpis"><div class="card kpi blue"><div class="label">Saldo do mês</div><div class="value">${money(t.balance)}</div></div><div class="card kpi green"><div class="label">Taxa de poupança</div><div class="value">${saving.toFixed(1)}%</div></div><div class="card kpi gold"><div class="label">XP da família</div><div class="value">${account.children.reduce((s,c)=>s+c.xp,0)}</div></div><div class="card kpi coral"><div class="label">Aguardando aprovação</div><div class="value">${awaiting}</div></div></div><div class="insights">${insights(t,prev,cat)}</div><div class="grid two"><section class="card panel"><div class="panel-head"><div><div class="panel-title">Receitas x despesas — 6 meses</div><div class="panel-sub">Comparativo mensal</div></div></div><div id="sixMonthChart" class="svg-chart"></div></section><section class="card panel"><div class="panel-head"><div><div class="panel-title">Despesas por categoria</div><div class="panel-sub">${monthLabel(state.month)}</div></div></div><div id="categoryChart" class="svg-chart"></div></section></div><div class="grid two" style="margin-top:18px"><section class="card panel"><div class="panel-head"><div><div class="panel-title">Progresso das metas</div><div class="panel-sub">Objetivos familiares e individuais</div></div></div>${account.goals.map(g=>goalHTML(g)).join('')||empty('Nenhuma meta.')}</section><section class="card panel"><div class="panel-head"><div><div class="panel-title">XP por criança</div><div class="panel-sub">Nível atual</div></div></div>${account.children.map(c=>childHTML(c)).join('')||empty('Nenhuma criança.')}</section></div>`;}
function getPreviousMonth(key){const d=new Date(`${key}-01T12:00:00`);d.setMonth(d.getMonth()-1);return d.toISOString().slice(0,7);}
function expenseByCategory(month){const map={};account.transactions.filter(t=>t.type==='expense'&&monthKey(t.date)===month).forEach(t=>map[t.category]=(map[t.category]||0)+Number(t.amount||0));return map;}
function insights(t,prev,cat){const arr=[];if(prev.expense&&t.expense>prev.expense)arr.push(`Você gastou ${Math.round((t.expense/prev.expense-1)*100)}% a mais que no mês anterior.`);else if(prev.expense&&t.expense<prev.expense)arr.push(`As despesas caíram ${Math.round((1-t.expense/prev.expense)*100)}% em relação ao mês anterior.`);const top=Object.entries(cat).sort((a,b)=>b[1]-a[1])[0];if(top)arr.push(`A categoria com maior gasto no mês é ${top[0]}, com ${money(top[1])}.`);if(t.income&&t.balance>0)arr.push(`A taxa de poupança atual é ${(t.balance/t.income*100).toFixed(1)}%.`);return `<div class="insight-grid">${arr.map(x=>`<div class="alert blue"><span>i</span><div><strong>Insight</strong><small>${escapeHTML(x)}</small></div></div>`).join('')||empty('Cadastre mais movimentações para receber insights.')}</div>`;}
function setupRelatorios(){fillMonthSelect($('reportMonth'));$('reportMonth').value=state.month;$('reportMonth').onchange=e=>{state.month=e.target.value;renderCurrent();};$('printReport').onclick=()=>window.print();requestAnimationFrame(()=>{drawSixMonthChart($('sixMonthChart'));drawCategoryChart($('categoryChart'));});}
function drawSixMonthChart(box){if(!box)return;const months=[];for(let i=5;i>=0;i--){const d=new Date(`${state.month}-01T12:00:00`);d.setMonth(d.getMonth()-i);months.push(d.toISOString().slice(0,7));}const vals=months.map(m=>({m,...totals(m)}));const max=Math.max(1,...vals.flatMap(x=>[x.income,x.expense]));const w=700,h=280,p=35,bar=24,gap=22;let svg=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Gráfico de receitas e despesas dos últimos seis meses"><line x1="${p}" y1="${h-p}" x2="${w-p}" y2="${h-p}" stroke="#cbd5db"/><line x1="${p}" y1="${p}" x2="${p}" y2="${h-p}" stroke="#cbd5db"/>`;vals.forEach((x,i)=>{const base=p+i*(bar*2+gap+20),ih=(h-2*p)*x.income/max,eh=(h-2*p)*x.expense/max;svg+=`<rect x="${base}" y="${h-p-ih}" width="${bar}" height="${ih}" rx="4" fill="#2f6f95"><title>${monthLabel(x.m)} — receitas ${money(x.income)}</title></rect><rect x="${base+bar+5}" y="${h-p-eh}" width="${bar}" height="${eh}" rx="4" fill="#d96b5f"><title>${monthLabel(x.m)} — despesas ${money(x.expense)}</title></rect><text x="${base+bar}" y="${h-10}" text-anchor="middle" font-size="10" fill="#6f7d89">${escapeHTML(monthLabel(x.m))}</text>`;});svg+=`<rect x="${w-170}" y="15" width="10" height="10" fill="#2f6f95"/><text x="${w-155}" y="24" font-size="10">Receitas</text><rect x="${w-95}" y="15" width="10" height="10" fill="#d96b5f"/><text x="${w-80}" y="24" font-size="10">Despesas</text></svg>`;box.innerHTML=svg;}
function drawCategoryChart(box){if(!box)return;const data=Object.entries(expenseByCategory(state.month)).sort((a,b)=>b[1]-a[1]);const max=Math.max(1,...data.map(x=>x[1]));box.innerHTML=data.length?`<svg viewBox="0 0 700 ${Math.max(240,data.length*48)}" role="img" aria-label="Despesas por categoria">${data.map(([name,val],i)=>{const y=28+i*45,w=500*(val/max);return `<text x="0" y="${y+14}" font-size="12" fill="#243746">${escapeHTML(name)}</text><rect x="150" y="${y}" width="500" height="24" rx="5" fill="#edf0f2"/><rect x="150" y="${y}" width="${w}" height="24" rx="5" fill="#3f806c"/><text x="660" y="${y+16}" text-anchor="end" font-size="11" fill="#243746">${money(val)}</text>`;}).join('')}</svg>`:empty('Nenhuma despesa no período.');}

function configuracoes(){return `<div class="page-head"><div><span class="eyebrow">Administração</span><h1>Configurações</h1><p>Dados da família, categorias, orçamentos e segurança do protótipo.</p></div></div><div class="grid two"><section class="card panel"><h2 class="section-heading">Família</h2><form id="familyForm" class="form-grid"><label>Nome da família<input id="familyName" value="${htmlAttr(account.familyName)}" required></label><label>Responsável<input id="responsible" value="${htmlAttr(account.responsible)}" required></label><label class="full">E-mail<input id="familyEmail" type="email" value="${htmlAttr(account.email)}" required></label><label class="check-field full"><input id="notifications" type="checkbox" ${account.settings.notifications?'checked':''}> Notificações internas</label><label class="check-field full"><input id="weeklySummary" type="checkbox" ${account.settings.weeklySummary?'checked':''}> Resumo semanal</label><div class="form-actions full"><button class="btn btn-primary">Salvar alterações</button></div></form></section><section class="card panel"><h2 class="section-heading">Segurança</h2><div class="setting-row"><div><strong>Senha do responsável</strong><small>Armazenada com PBKDF2 + salt.</small></div><button class="btn" id="changePassword">Alterar senha</button></div><div class="setting-row"><div><strong>Sessão</strong><small>Expira após 30 minutos de inatividade.</small></div><button class="btn" id="logoutSettings">Sair</button></div><div class="setting-row"><div><strong>Privacidade</strong><small>O cadastro de menores exige consentimento do responsável.</small></div><span class="badge green">Ativo</span></div></section></div><section class="card panel" id="categorias" style="margin-top:18px"><div class="panel-head"><div><h2 class="section-heading">Categorias</h2><div class="panel-sub">Personalize nome, cor e ícone usados nas finanças.</div></div><button class="btn" id="newCategory">+ Categoria</button></div><div id="categoryList">${categoryList()}</div></section><section class="card panel" style="margin-top:18px"><div class="panel-head"><div><h2 class="section-heading">Orçamento mensal</h2><div class="panel-sub">Alertas automáticos em 80% e 100% do limite.</div></div><button class="btn" id="newBudget">+ Orçamento</button></div><div id="budgetList">${budgetList()}</div></section><section class="card panel danger-panel" style="margin-top:18px"><h2 class="section-heading">Dados</h2><div class="setting-row"><div><strong>Backup JSON</strong><small>Exporte ou importe uma cópia completa dos dados.</small></div><div class="toolbar-right"><button class="btn" id="exportBackup">Exportar backup</button><button class="btn" id="importBackup">Importar backup</button></div></div><div class="setting-row"><div><strong>Restaurar dados de demonstração</strong><small>Substitui os dados da família atual por dados de exemplo.</small></div><button class="btn btn-danger" id="resetDemo">Restaurar</button></div></section>`;}
function categoryList(){return account.categories.map(c=>`<div class="setting-row"><div><span class="category-dot" style="background:${htmlAttr(c.color)}"></span><strong>${escapeHTML(c.icon)} ${escapeHTML(c.name)}</strong></div><div class="toolbar-right"><button class="btn btn-small" data-edit-cat="${c.id}">Editar</button><button class="btn btn-small btn-danger-outline" data-delete-cat="${c.id}">Excluir</button></div></div>`).join('')||empty('Nenhuma categoria.');}
function budgetList(){return account.budgets.map(b=>{const spent=account.transactions.filter(t=>t.type==='expense'&&monthKey(t.date)===b.month&&t.category===b.category).reduce((s,t)=>s+t.amount,0);const p=Math.round(spent/b.limit*100);return `<div class="budget-row"><div><strong>${escapeHTML(b.category)}</strong><small>${monthLabel(b.month)} · limite ${money(b.limit)}</small></div><div class="budget-progress"><div class="progress"><span class="${p>=100?'danger-fill':p>=80?'warn-fill':''}" style="width:${Math.min(100,p)}%"></span></div><small>${money(spent)} / ${money(b.limit)} (${p}%) ${p>=100?'· limite atingido':p>=80?'· atenção: 80%+':''}</small></div><div class="toolbar-right"><button class="btn btn-small" data-edit-budget="${b.id}">Editar</button><button class="btn btn-small btn-danger-outline" data-delete-budget="${b.id}">Excluir</button></div></div>`;}).join('')||empty('Nenhum orçamento cadastrado.');}
function setupConfiguracoes(){ $('familyForm').onsubmit=e=>{e.preventDefault();account.familyName=$('familyName').value.trim();account.responsible=$('responsible').value.trim();account.email=$('familyEmail').value.trim();account.users.find(u=>u.id===session.userId).name=account.responsible;account.users.find(u=>u.id===session.userId).email=account.email;account.settings.notifications=$('notifications').checked;account.settings.weeklySummary=$('weeklySummary').checked;saveAccount();renderCurrent();toast('Configurações salvas.');};$('changePassword').onclick=changePassword;$('logoutSettings').onclick=logout;$('newCategory').onclick=categoryModal;$('newBudget').onclick=budgetModal;$('exportBackup').onclick=exportBackup;$('importBackup').onclick=importBackup;$('resetDemo').onclick=()=>confirmAction('Restaurar demonstração','Todos os dados atuais desta família serão substituídos pelos dados de demonstração.',()=>{resetDemo();clearSession();location.href='login.html?demo=1';});document.querySelectorAll('[data-edit-cat]').forEach(b=>b.onclick=()=>categoryModal(b.dataset.editCat));document.querySelectorAll('[data-delete-cat]').forEach(b=>b.onclick=()=>deleteCategory(b.dataset.deleteCat));document.querySelectorAll('[data-edit-budget]').forEach(b=>b.onclick=()=>budgetModal(b.dataset.editBudget));document.querySelectorAll('[data-delete-budget]').forEach(b=>b.onclick=()=>deleteBudget(b.dataset.deleteBudget));}
function categoryModal(id=null){const c=id?account.categories.find(x=>x.id===id):null;openModal(id?'Editar categoria':'Nova categoria',`<form id="catForm"><label>Nome<input id="catName" value="${htmlAttr(c?.name||'')}" required></label><label>Ícone<input id="catIcon" maxlength="4" value="${htmlAttr(c?.icon||'•')}" required></label><label>Cor<input id="catColor" type="color" value="${htmlAttr(c?.color||'#2f6f95')}" required></label><div class="form-actions"><button class="btn" id="cancelCat">Cancelar</button><button class="btn btn-primary">Salvar</button></div></form>`,()=>{$('cancelCat').onclick=closeModal;$('catForm').onsubmit=e=>{e.preventDefault();const name=$('catName').value.trim();if(!name){toast('Informe o nome.','error');return;}if(id)Object.assign(c,{name,icon:$('catIcon').value.trim(),color:$('catColor').value});else account.categories.push({id:uid('cat'),name,icon:$('catIcon').value.trim(),color:$('catColor').value});saveAccount();closeModal();renderCurrent();toast('Categoria salva.');};});}
function deleteCategory(id){const c=account.categories.find(x=>x.id===id);if(!c)return;confirmAction('Excluir categoria',`Excluir “${c.name}”? Lançamentos antigos continuarão com o texto já salvo.`,()=>{account.categories=account.categories.filter(x=>x.id!==id);saveAccount();renderCurrent();toast('Categoria excluída.');});}
function budgetModal(id=null){const b=id?account.budgets.find(x=>x.id===id):null;openModal(id?'Editar orçamento':'Novo orçamento',`<form id="budgetForm" class="form-grid"><label>Categoria<select id="budgetCategory">${account.categories.map(c=>`<option ${b?.category===c.name?'selected':''}>${escapeHTML(c.name)}</option>`).join('')}</select></label><label>Mês<input id="budgetMonth" type="month" value="${b?.month||state.month}" required></label><label>Limite (R$)<input id="budgetLimit" type="number" min="0.01" step="0.01" value="${b?.limit||''}" required></label><div class="form-actions full"><button class="btn" id="cancelBudget">Cancelar</button><button class="btn btn-primary">Salvar</button></div></form>`,()=>{$('cancelBudget').onclick=closeModal;$('budgetForm').onsubmit=e=>{e.preventDefault();const limit=Number($('budgetLimit').value);if(!(limit>0))return toast('Informe um limite válido.','error');if(id)Object.assign(b,{category:$('budgetCategory').value,month:$('budgetMonth').value,limit});else account.budgets.push({id:uid('budget'),category:$('budgetCategory').value,month:$('budgetMonth').value,limit});saveAccount();closeModal();renderCurrent();toast('Orçamento salvo.');};});}
function deleteBudget(id){confirmAction('Excluir orçamento','Excluir este orçamento mensal?',()=>{account.budgets=account.budgets.filter(x=>x.id!==id);saveAccount();renderCurrent();toast('Orçamento excluído.');});}
function changePassword(){openModal('Alterar senha',`<form id="passwordForm"><label>Senha atual<input id="oldPassword" type="password" required></label><label>Nova senha<input id="newPassword" type="password" minlength="8" required></label><label>Confirmar nova senha<input id="confirmPassword" type="password" minlength="8" required></label><div class="form-actions"><button class="btn" id="cancelPassword">Cancelar</button><button class="btn btn-primary">Salvar</button></div></form>`,()=>{$('cancelPassword').onclick=closeModal;$('passwordForm').onsubmit=async e=>{e.preventDefault();const u=account.users.find(x=>x.id===session.userId);if(!await verifySecret($('oldPassword').value,u.password)){toast('Senha atual incorreta.','error');return;}if($('newPassword').value.length<8||$('newPassword').value!==$('confirmPassword').value){toast('A nova senha deve ter pelo menos 8 caracteres e coincidir.','error');return;}u.password=await hashSecret($('newPassword').value);saveAccount();closeModal();toast('Senha alterada.');};});}
function exportBackup(){downloadBlob(exportStore(),'educafam-backup-v2.json','application/json;charset=utf-8');toast('Backup exportado.');}
function importBackup(){openModal('Importar backup JSON',`<p class="modal-copy">O arquivo deve ser um backup do EducaFAM com <strong>accounts</strong> e versão de esquema.</p><input id="backupFile" type="file" accept="application/json,.json"><div class="form-actions"><button class="btn" id="cancelBackup">Cancelar</button><button class="btn btn-primary" id="processBackup">Importar</button></div>`,()=>{$('cancelBackup').onclick=closeModal;$('processBackup').onclick=()=>{const file=$('backupFile').files[0];if(!file)return toast('Selecione um backup.','error');const r=new FileReader();r.onload=()=>{try{importStore(r.result);closeModal();toast('Backup importado. Recarregando...');setTimeout(()=>location.reload(),500);}catch(e){toast(e.message||'Backup inválido.','error');}};r.readAsText(file);};});}

function downloadBlob(content,name,type){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();URL.revokeObjectURL(url);}
function registerLogin(){
  const tab=document.querySelector('.login-tabs .active')?.dataset.tab||'responsible';
  if(tab==='child')return childLoginPage();
  return `<div class="login-brand"><div class="brand-mark">EF</div><span class="brand-name">Educa<span>FAM</span></span><p>Finanças em família, aprendizado para a vida.</p><div class="login-features"><span>✓ Planejamento financeiro</span><span>✓ Missões com aprovação</span><span>✓ Educação financeira infantil</span></div></div><section class="login-card"><div class="login-tabs"><button type="button" class="active" data-tab="responsible">Responsável</button><button type="button" data-tab="child">Criança</button></div><span class="eyebrow">ÁREA DA FAMÍLIA</span><h1>Entrar</h1><p class="muted">Use sua conta para acompanhar orçamento, metas e atividades.</p><form id="loginForm"><label>E-mail<input type="email" id="email" autocomplete="email" required></label><label>Senha<input type="password" id="password" autocomplete="current-password" required></label><button class="btn btn-primary btn-full">Entrar</button></form><div class="login-links"><button type="button" class="link-button" id="showRegister">Criar uma família</button><span>•</span><button type="button" class="link-button" id="showMigration">Recuperar dados antigos</button></div><div class="demo-box"><strong>Conta de demonstração</strong><small>E-mail: familia@educafam.local · Senha: 123456</small></div></section>`;
}
function childLoginPage(){return `<div class="login-brand child-brand"><div class="brand-mark">EF</div><span class="brand-name">Educa<span>FAM</span></span><p>Seu espaço para aprender, cumprir missões e cuidar dos seus objetivos.</p></div><section class="login-card"><div class="login-tabs"><button type="button" data-tab="responsible">Responsável</button><button type="button" class="active" data-tab="child">Criança</button></div><span class="eyebrow">ESPAÇO INFANTIL</span><h1>Entrar como criança</h1><p class="muted">Informe o e-mail da família, escolha seu perfil e digite seu PIN.</p><form id="childLoginForm"><label>E-mail da família<input type="email" id="childFamilyEmail" required></label><label>Quem é você?<select id="childSelector" required><option value="">Digite o e-mail primeiro</option></select></label><label>PIN de 4 dígitos<input type="password" id="childLoginPin" inputmode="numeric" maxlength="4" pattern="[0-9]{4}" required></label><button class="btn btn-primary btn-full">Entrar</button></form><div class="login-links"><button type="button" class="link-button" id="backResponsible">Voltar para responsável</button></div></section>`;}
function setupLogin(){document.querySelectorAll('.login-tabs button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.login-tabs button').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.querySelector('.login-shell').innerHTML=registerLogin();setupLogin();});$('loginForm')?.addEventListener('submit',async e=>{e.preventDefault();const email=$('email').value.trim().toLowerCase(),password=$('password').value;const store=getStore();let acc=store.accounts.find(a=>a.email.toLowerCase()===email||a.users.some(u=>u.email.toLowerCase()===email));if(!acc){toast('Conta não encontrada.','error');return;}const user=acc.users.find(u=>u.email.toLowerCase()===email)||acc.users.find(u=>u.role==='responsible');if(!user){toast('Usuário responsável não encontrado.','error');return;}account=acc;if(user.needsPasswordSetup){delete user.needsPasswordSetup;user.password=DEMO_HASH;saveAccount();}if(!await verifySecret(password,user.password)){toast('E-mail ou senha inválidos.','error');return;}setSession({accountId:acc.id,userId:user.id,role:'responsible',expiresAt:Date.now()+30*60*1000,lastActivity:Date.now()});location.href='index.html';});$('showRegister')?.addEventListener('click',registerFamilyModal);$('showMigration')?.addEventListener('click',migrationModal);$('childFamilyEmail')?.addEventListener('change',loadChildOptions);$('backResponsible')?.addEventListener('click',()=>{document.querySelector('.login-shell').innerHTML=registerLogin();setupLogin();});}
function loadChildOptions(){const email=$('childFamilyEmail').value.trim().toLowerCase();const acc=getStore().accounts.find(a=>a.email.toLowerCase()===email);const sel=$('childSelector');sel.innerHTML=acc?`<option value="">Selecione</option>${acc.children.map(c=>`<option value="${c.id}">${escapeHTML(c.avatar)} ${escapeHTML(c.name)}</option>`).join('')}`:'<option value="">Família não encontrada</option>';}
function registerFamilyModal(){openModal('Criar família',`<form id="registerForm" class="form-grid"><label>Nome da família<input id="rFamily" maxlength="80" required></label><label>Nome do responsável<input id="rName" maxlength="60" required></label><label class="full">E-mail<input id="rEmail" type="email" required></label><label>Senha<input id="rPassword" type="password" minlength="8" required></label><label>Confirmar senha<input id="rPassword2" type="password" minlength="8" required></label><label class="check-field full"><input id="rConsent" type="checkbox" required> Declaro ser responsável pela família e concordo com o armazenamento local dos dados.</label><div class="form-actions full"><button class="btn" id="cancelRegister">Cancelar</button><button class="btn btn-primary">Criar família</button></div></form>`,()=>{$('cancelRegister').onclick=closeModal;$('registerForm').onsubmit=async e=>{e.preventDefault();const email=$('rEmail').value.trim().toLowerCase();if($('rPassword').value.length<8||$('rPassword').value!==$('rPassword2').value){toast('As senhas devem ter pelo menos 8 caracteres e coincidir.','error');return;}const store=getStore();if(store.accounts.some(a=>a.email.toLowerCase()===email)){toast('Este e-mail já está cadastrado.','error');return;}const userId=uid('user'),acc={id:uid('fam'),name:$('rFamily').value.trim(),familyName:$('rFamily').value.trim(),responsible:$('rName').value.trim(),email,consentMinor:$('rConsent').checked,createdAt:todayISO(),users:[{id:userId,name:$('rName').value.trim(),email,role:'responsible',password:await hashSecret($('rPassword').value)}],children:[],transactions:[],categories:clone(demoFamily().categories),goals:[],missions:[],xpHistory:[],budgets:[],notifications:[],settings:{notifications:true,weeklySummary:true,familyTheme:'light'}};store.accounts.push(acc);saveStore(store);account=acc;setSession({accountId:acc.id,userId,role:'responsible',expiresAt:Date.now()+30*60*1000,lastActivity:Date.now()});closeModal();location.href='index.html';};});}
function migrationModal(){const legacy=getLegacyInfo();openModal('Recuperar dados antigos',legacy?`<p class="modal-copy">Encontramos dados da versão anterior do EducaFAM. Os dados podem ser recuperados sem bloquear o acesso. Para a conta migrada, use a senha de demonstração <strong>123456</strong> e altere-a depois em Configurações.</p><button class="btn btn-primary btn-full" id="startMigration">Migrar e entrar</button>`:`<div class="empty">Nenhum dado antigo foi encontrado neste navegador.</div>`,()=>{$('startMigration')?.addEventListener('click',()=>{const store=getStore();let acc=store.accounts.find(a=>a.users?.some(u=>u.needsPasswordSetup))||store.accounts.find(a=>a.email?.toLowerCase()==='familia@educafam.local');if(!acc){toast('Não foi possível localizar os dados antigos.','error');return;}const user=acc.users?.find(u=>u.role==='responsible')||acc.users?.[0];if(!user){toast('Usuário responsável não encontrado.','error');return;}user.password=DEMO_HASH;delete user.needsPasswordSetup;account=acc;upsertAccount(acc);closeModal();setSession({accountId:acc.id,userId:user.id,role:'responsible',expiresAt:Date.now()+30*60*1000,lastActivity:Date.now()});location.href='index.html';});});}
function showFirstPasswordSetup(acc,user){openModal('Defina sua nova senha',`<p class="modal-copy">Os dados antigos foram encontrados, mas a senha da versão anterior não pode ser recuperada. Defina uma nova senha com pelo menos 8 caracteres.</p><form id="firstPassword"><label>Nova senha<input id="firstPass" type="password" minlength="8" required></label><label>Confirmar senha<input id="firstPass2" type="password" minlength="8" required></label><div class="form-actions"><button class="btn" id="cancelFirst">Cancelar</button><button class="btn btn-primary">Salvar e entrar</button></div></form>`,()=>{$('cancelFirst').onclick=closeModal;$('firstPassword').onsubmit=async e=>{e.preventDefault();if($('firstPass').value.length<8||$('firstPass').value!==$('firstPass2').value)return toast('As senhas não coincidem ou são muito curtas.','error');user.password=await hashSecret($('firstPass').value);delete user.needsPasswordSetup;saveAccount();closeModal();setSession({accountId:acc.id,userId:user.id,role:'responsible',expiresAt:Date.now()+30*60*1000,lastActivity:Date.now()});location.href='index.html';};});}
function setupLoginPage(){const shell=document.querySelector('.login-shell');shell.innerHTML=registerLogin();setupLogin();const q=new URLSearchParams(location.search);if(q.has('expired'))toast('Sua sessão expirou por inatividade.','error');if(q.has('logout'))toast('Sessão encerrada.');if(q.has('demo'))toast('Dados de demonstração restaurados.');}

function renderCurrent(){if(PAGE==='dashboard')document.getElementById('app').innerHTML='';const content=PAGE==='dashboard'?dashboard():PAGE==='financas'?finance():PAGE==='metas'?metas():PAGE==='missoes'?missoes():PAGE==='criancas'?criancas():PAGE==='relatorios'?relatorios():PAGE==='configuracoes'?configuracoes():'';layout(content);if(PAGE==='dashboard'&&session.role==='child')setupChildDashboard();if(PAGE==='financas')setupFinance();if(PAGE==='metas')setupMetas();if(PAGE==='missoes')setupMissoes();if(PAGE==='criancas')setupCriancas();if(PAGE==='relatorios')setupRelatorios();if(PAGE==='configuracoes')setupConfiguracoes();}

document.addEventListener('DOMContentLoaded',()=>{
  if('serviceWorker' in navigator && location.protocol!=='file:') navigator.serviceWorker.register('sw.js').catch(()=>{});
  if(PAGE==='login'){setupLoginPage();return;}
  guard();if(!session)return;account=getAccount(session.accountId);if(!account){clearSession();location.href='login.html';return;}materializeRecurring();renderCurrent();
});
